package org.sleepwell.app;
import android.app.*;import android.os.Bundle;import android.widget.*;import android.view.*;
/** Silent configuration. Uses the existing explicit Play, timer and focus-controlled player. */
public final class BinauralSettingsActivity extends Activity {
 private NightDialStereoPreview sourcePreview;private SoundMix draft;private long revision;private String error="";private TextView frequencies,carrierValue,beatValue;private android.content.SharedPreferences settings;
 @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);settings=SoundPreferences.factory.open(this);try{draft=SoundPreferences.load(settings);revision=SoundPreferences.revision(settings);}catch(RuntimeException failure){error="Saved mix could not be read. Return to Sleep sounds and choose a new mix.";draft=null;}if(draft!=null&&state!=null){draft.binauralCarrier=state.getInt("carrier",draft.binauralCarrier);draft.binauralBeat=state.getInt("beat",draft.binauralBeat);revision=state.getLong("revision",revision);try{BinauralTones.validate(draft.binauralCarrier,draft.binauralBeat);}catch(IllegalArgumentException invalid){draft.binauralCarrier=200;draft.binauralBeat=6;error="Draft frequencies were invalid; defaults restored.";}}render();}
 private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Binaural stereo tones",this::finish);Design.space(body,16);if(draft==null){Design.text(body,error,15,500,Design.BROWN);return;}frequencies=Design.text(body,"",28,600,Design.INK);Design.space(body,8);Design.text(body,"Two quiet sine tones, one per channel. Stereo headphones are needed to hear the frequency difference; a mono route combines the tones.",14,400,Design.MUTED);Design.space(body,12);sourcePreview=new NightDialStereoPreview(this,draft.binauralCarrier,draft.binauralCarrier+draft.binauralBeat);body.addView(sourcePreview,new LinearLayout.LayoutParams(-1,Design.dp(this,176*Math.max(1,Design.fontScale(this)))));Design.space(body,20);carrierValue=Design.text(body,"",16,600,Design.INK);SeekBar carrier=new SeekBar(this);carrier.setMax(300);carrier.setProgress(draft.binauralCarrier-100);carrier.setContentDescription("Left carrier frequency in hertz");SoundSliders.style(carrier);carrier.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar bar){}public void onStopTrackingTouch(SeekBar bar){}public void onProgressChanged(SeekBar bar,int value,boolean user){if(user){draft.binauralCarrier=100+value;labels();}}});body.addView(carrier,new LinearLayout.LayoutParams(-1,Design.dp(this,48)));Design.space(body,12);beatValue=Design.text(body,"",16,600,Design.INK);SeekBar beat=new SeekBar(this);beat.setMax(19);beat.setProgress(draft.binauralBeat-1);beat.setContentDescription("Right channel frequency difference in hertz");SoundSliders.style(beat);beat.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar bar){}public void onStopTrackingTouch(SeekBar bar){}public void onProgressChanged(SeekBar bar,int value,boolean user){if(user){draft.binauralBeat=1+value;labels();}}});body.addView(beat,new LinearLayout.LayoutParams(-1,Design.dp(this,48)));Design.space(body,20);NightDialDetails.disclosure(body,"About stereo tones","100-400 Hz left carrier, with 1-20 Hz added to the right channel. Generated locally as 48 kHz PCM16 stereo at 8% digital peak, before mix gain. No network or microphone. No brainwave, health, sleep-stage or treatment benefit is claimed. Keep headphone volume comfortable; phone media volume affects loudness.");Design.space(body,12);Design.text(body,"Manual Play only. Saving pauses the mix and turns off tracking auto-play. Return to Sleep sounds, then press Play.",13,400,Design.MUTED);if(!error.isEmpty()){Design.space(body,12);Design.text(body,error,13,500,Design.BROWN);}LinearLayout footer=RecordUi.footer(body);Design.button(footer,"Use stereo tones",true,this::save);Design.button(footer,"Cancel",false,this::finish);labels();}
 private void labels(){if(frequencies==null||draft==null)return;frequencies.setText(draft.binauralCarrier+" Hz  /  "+(draft.binauralCarrier+draft.binauralBeat)+" Hz");carrierValue.setText("Left carrier  "+draft.binauralCarrier+" Hz");beatValue.setText("Right difference  +"+draft.binauralBeat+" Hz");if(sourcePreview!=null)sourcePreview.frequencies(draft.binauralCarrier,draft.binauralCarrier+draft.binauralBeat);}
 private void save(){try{BinauralTones.validate(draft.binauralCarrier,draft.binauralBeat);SoundMix choice=draft.copy();choice.primary=BinauralTones.NAME;choice.withTracking=false;choice.validate();if(SoundPreferences.revision(settings)!=revision){error="The mix changed while this page was open. Reopen it before saving.";render();return;}SleepSoundService.pauseForSelection();if(!SoundPreferences.saveIfRevision(settings,revision,choice)){error="The mix changed. Reopen this page before saving.";render();return;}SoundPreferences.error(this,"");SleepSoundService.update(this);finish();}catch(RuntimeException failure){error=failure.getMessage()==null?"Stereo settings could not be saved.":failure.getMessage();render();}}
 @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(draft!=null){state.putInt("carrier",draft.binauralCarrier);state.putInt("beat",draft.binauralBeat);state.putLong("revision",revision);}}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}
